['Here is an example implementation in C:

```c
#include <string.h>

int string_length(char* str) {
    int len = 0;
    while (*str != '\0') {
        len++;
        str++;
    }
    return len;
}

void copy_bytes(void* dest, void* src, int bytes_to_copy) {
    char* dst = (char*)dest;
    char* src_str = (char*)src;

    for(int i = 0; i < bytes_to_copy; i++) {
        dst[i] = src_str[i];
    }
}

int main() {
    char buffer[100];
    const char* str = "Hello";

    // Copy the string to the buffer
    copy_bytes(buffer, str, strlen(str));

    printf("Copied string: %s\n", buffer);

    int len = string_length(buffer);
    printf("Length of copied string: %d\n", len);

    return 0;
}
```

