// Function to calculate quarterly sales for a given array of monthly sales
void getQuarterlySales(int months[], int quarters[4]) {
    int quarter = 0;
    for (int i = 0; i < 12; i++) {
        if (i % 3 == 0) {
            quarter++;
        }
        quarters[quarter - 1] += months[i];
    }

    // Print out the quarterly sales
    printf("Quarterly Sales: $");
    for (int i = 0; i < 4; i++) {
        printf("%d, ", quarters[i]);
    }
    printf("\n");
}

int main() {
    int months[12];

    // Get monthly sales for each month
    for (int i = 1; i <= 12; i++) {
        months[i - 1] = getMonthlySales(i);
    }

    // Calculate and print the quarterly sales
    int quarters[4];
    for (int i = 0; i < 4; i++) {
        quarters[i] = 0;
    }
    getQuarterlySales(months, quarters);

    return 0;
}
