['Here's the Python code using Flask to create a simple web application:

```Python
from flask import Flask, request, jsonify
app = Flask(__name__)

# Dictionary of products and their prices
products = {
    "A": {"price": 5},
    "B": {"price": 10},
    "C": {"price": 7.50}
}

@app.route('/product_price', methods=['GET'])
def get_product_price():
    product_code = request.args.get('code')
    quantity = int(request.args.get('quantity'))

    if product_code in products:
        price = products[product_code]['price']
        return jsonify({'price': float(price) * quantity})
    else:
        return jsonify({'error': 'Product not found'}), 404

if __name__ == '__main__':
    app.run(debug=True, port=5000)
```

