['Here is a simple C program that accepts a command-line argument, trims any trailing whitespace, and then prints it out:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <argument>\n", argv[0]);
        return 1;
    }

    char* arg = argv[1];
    int len = strlen(arg);
    while (len > 0 && isspace(arg[len - 1])) {
        len--;
    }
    arg[len] = '\0';
    printf("%s\n", arg);

    return 0;
}
```

