typedef struct {
    FILE* req; // Request file stream
    FILE* res; // Response file stream
} HttpRequest;

// Function to handle the HTTP "hello page" request
void http_hello_page(HttpRequest* req_res) {
    char username[256];
    int i = 0;

    // Read the username from the request
    while (1) {
        int c = fgetc(req_res->req);
        if (c == '\n') break;
        username[i++] = (char)c;
    }
    username[i] = '\0';

    // Construct the response
    char* response = malloc(1024);
    sprintf(response, "hello %s", username);

    // Write the response to the file stream
    fwrite(response, 1, strlen(response), req_res->res);
    free(response);
}

