def auth_mod(username, password, session):
    # Replace with your actual logic to determine if a user is a moderator
    return username == "moderator_username" and password == "moderator_password"

@app.route('/check_mod', methods=['GET'])
def check_mod():
    username = request.args.get('username')
    password = request.args.get('password')
    session = request.args.get('session')

    if not all([username, password, session]):
        return jsonify({'error': 'All parameters are required'}), 400

    is_mod = auth_mod(username, password, session)

    if is_mod:
        return jsonify({'moderator': True})
    else:
        return jsonify({'moderator': False})

if __name__ == '__main__':
    app.run(debug=True)
```

